const LESSONS = {"en":{"foundations":{"title":"Stock Market Foundations","level":"beginner","time":"6 lessons","summary":"What a share is, how exchanges work, and how an order becomes a trade."},"investing":{"title":"Investing & Wealth Building","level":"beginner","time":"8 lessons","summary":"Set goals, understand your time horizon, diversify, and let compounding work over years."},"sip-mutual-funds":{"title":"SIP & Mutual Funds","level":"beginner","time":"7 lessons","summary":"How a Systematic Investment Plan works, what NAV means, and how to read fund costs."},"reading-charts":{"title":"Reading Charts","level":"beginner","time":"6 lessons","summary":"Understand line, bar and candlestick charts, OHLC data, and volume."},"fundamental-analysis":{"title":"Fundamental Analysis","level":"intermediate","time":"9 lessons","summary":"Evaluate a business using its financial statements, key ratios and quality checks."},"technical-analysis":{"title":"Technical Analysis","level":"intermediate","time":"10 lessons","summary":"Study price and volume patterns, trends, support, resistance and common indicators."},"swing-trading":{"title":"Swing Trading","level":"intermediate","time":"8 lessons","summary":"Hold trades for days to weeks using clear setups, entry and exit rules, and a trade journal.","sections":[{"h":"What is swing trading?","p":"Swing trading aims to capture a price move that usually lasts a few days to a few weeks. It sits between intraday trading (same day) and investing (months to years). It needs patience and planning. Holding overnight also exposes you to gaps, where the price opens far from your stop."},{"h":"A complete trade plan","ul":["Setup: why you are entering, for example a breakout above resistance on rising volume.","Entry: the price or condition that triggers the trade.","Stop loss: the price at which you accept the idea was wrong.","Target: where you plan to take profit, with a reward-to-risk ratio you accept, such as 2:1."]},{"h":"Position sizing","p":"Decide the most you will lose on one trade, for example 1% of capital. Position size = maximum loss ÷ (entry minus stop, per share). Example: ₹1,00,000 capital and 1% risk gives ₹1,000. With entry at ₹250 and stop at ₹240, the distance is ₹10, so the size is 100 shares. This excludes costs and slippage."},{"h":"Keep a trade journal","p":"Record the setup, reason, size, result and any mistakes. Review monthly to see which setups actually work for you."}]},"risk-management":{"title":"Risk Management","level":"intermediate","time":"7 lessons","summary":"Protect your capital with position sizing, stop losses, exposure limits and a drawdown plan."},"intraday-trading":{"title":"Intraday Trading","level":"advanced","time":"9 lessons","summary":"Trade within one session. Understand liquidity, order execution, margin and the real risks."},"futures-options":{"title":"Futures & Options","level":"advanced","time":"12 lessons","summary":"Understand futures, call and put options, strike price, expiry, margin and payoff, along with their risks."},"option-greeks":{"title":"Option Greeks & Strategies","level":"advanced","time":"10 lessons","summary":"Measure how option prices respond to price, time and volatility, and build defined-risk strategies."},"trading-psychology":{"title":"Trading Psychology","level":"advanced","time":"6 lessons","summary":"Recognise biases such as fear, greed and overtrading, and build a disciplined process."},"candlestick-patterns":{"title":"Candlestick and Chart Patterns","level":"intermediate","time":"25 patterns","summary":"Learn what each candle and chart shape signals, when it matters, how to confirm it, and the mistake to avoid."},"technical-indicators":{"title":"Technical Indicators","level":"intermediate","time":"10 indicators","summary":"Understand what moving averages, RSI, MACD, volume and other indicators measure, when to use each one, and how to use them in a trade."},"tax-basics":{"title":"Tax Basics for Indian Investors and Traders","level":"intermediate","time":"11 topics","summary":"How gains from shares, mutual funds, intraday and F&O are taxed in India, what records to keep, and where to verify the current rules."},"balance-sheet":{"title":"How to Read a Balance Sheet","level":"intermediate","time":"13 topics","summary":"What a balance sheet shows, how to read assets, liabilities and equity, and the ratios that reveal financial strength."},"cash-flow-statement":{"title":"How to Read a Cash Flow Statement","level":"intermediate","time":"13 topics","summary":"Where a company's real cash comes from and goes, and why cash flow can tell you more than profit."},"quarterly-results":{"title":"How to Read Quarterly Results","level":"intermediate","time":"13 topics","summary":"How to read the numbers in a quarterly results filing, compare them correctly, and spot one-off items."},"annual-report":{"title":"How to Read an Annual Report","level":"intermediate","time":"13 topics","summary":"The parts of a company's annual report, what each section tells you, and the warning signs to look for."},"shareholding-pattern":{"title":"Shareholding Pattern and Promoter Holding","level":"intermediate","time":"12 topics","summary":"Who owns a company, how promoter, institutional and public holdings change, and what pledged shares mean."},"valuation-basics":{"title":"Valuation Basics: What Is a Share Worth?","level":"advanced","time":"8 topics","summary":"P/E, P/B, EV/EBITDA, PEG and discounted cash flow explained, with their limits and how to combine them."},"corporate-actions":{"title":"Corporate Actions: Dividends, Bonus, Splits, Rights and Buybacks","level":"intermediate","time":"13 topics","summary":"What companies do with shares and cash, how each action changes the price and your holding, and how to avoid confusion on the ex-date."},"market-rules":{"title":"Market Rules & Investor Protection","level":"beginner","time":"10 topics","summary":"Market timings, settlement, price bands and circuit breakers, applying for IPOs, spotting scams and tips, and how to complain if something goes wrong."}},"hi":{"foundations":{"title":"शेयर बाज़ार की मूल बातें","level":"beginner","time":"6 पाठ","summary":"शेयर क्या है, एक्सचेंज कैसे काम करते हैं, और ऑर्डर ट्रेड में कैसे बदलता है।"},"investing":{"title":"निवेश और धन निर्माण","level":"beginner","time":"8 पाठ","summary":"लक्ष्य तय करें, समय-सीमा समझें, विविधीकरण करें और चक्रवृद्धि को वर्षों तक काम करने दें।"},"sip-mutual-funds":{"title":"SIP और म्यूचुअल फंड","level":"beginner","time":"7 पाठ","summary":"SIP कैसे काम करता है, NAV का मतलब क्या है, और फंड की लागत कैसे पढ़ें।"},"reading-charts":{"title":"चार्ट कैसे पढ़ें","level":"beginner","time":"6 पाठ","summary":"लाइन, बार और कैंडलस्टिक चार्ट, OHLC डेटा और वॉल्यूम समझें।"},"fundamental-analysis":{"title":"फंडामेंटल एनालिसिस","level":"intermediate","time":"9 पाठ","summary":"वित्तीय विवरण, प्रमुख अनुपात और गुणवत्ता जाँच से किसी कारोबार का मूल्यांकन करें।"},"technical-analysis":{"title":"टेक्निकल एनालिसिस","level":"intermediate","time":"10 पाठ","summary":"कीमत और वॉल्यूम पैटर्न, ट्रेंड, सपोर्ट, रेज़िस्टेंस और आम इंडिकेटर पढ़ें।"},"swing-trading":{"title":"स्विंग ट्रेडिंग","level":"intermediate","time":"8 पाठ","summary":"साफ़ सेटअप, एंट्री-एग्ज़िट नियम और ट्रेड जर्नल से कुछ दिनों से कुछ हफ़्तों तक ट्रेड रखें।","sections":[{"h":"स्विंग ट्रेडिंग क्या है?","p":"स्विंग ट्रेडिंग आमतौर पर कुछ दिनों से कुछ हफ़्तों तक चलने वाली कीमत की चाल को पकड़ने का प्रयास है। यह इंट्राडे (एक ही दिन) और निवेश (महीने-साल) के बीच आता है। इसके लिए धैर्य और योजना चाहिए। रात भर पोज़िशन रखने से गैप का जोखिम भी रहता है, जब कीमत आपके स्टॉप से काफ़ी दूर खुल जाए।"},{"h":"पूरा ट्रेड प्लान","ul":["सेटअप: आप क्यों एंट्री कर रहे हैं, जैसे वॉल्यूम के साथ रेज़िस्टेंस से ब्रेकआउट।","एंट्री: वह कीमत या शर्त जिस पर ट्रेड शुरू होगा।","स्टॉप लॉस: वह कीमत जहाँ आप मान लेंगे कि आपका विचार ग़लत था।","टारगेट: जहाँ मुनाफ़ा बुक करेंगे, और आपका स्वीकार्य जोखिम-इनाम अनुपात, जैसे 2:1।"]},{"h":"पोज़िशन साइज़","p":"तय करें कि एक ट्रेड में अधिकतम कितना नुकसान उठाएँगे, जैसे पूँजी का 1%। पोज़िशन साइज़ = अधिकतम नुकसान ÷ (एंट्री − स्टॉप), प्रति शेयर। उदाहरण: ₹1,00,000 पूँजी और 1% जोखिम = ₹1,000। एंट्री ₹250 और स्टॉप ₹240 है, यानी दूरी ₹10, तो साइज़ 100 शेयर। इसमें शुल्क और स्लिपेज शामिल नहीं हैं।"},{"h":"ट्रेड जर्नल रखें","p":"सेटअप, कारण, साइज़, नतीजा और गलतियाँ लिखें। हर महीने समीक्षा करें कि कौन से सेटअप आपके लिए सचमुच काम करते हैं।"}]},"risk-management":{"title":"जोखिम प्रबंधन","level":"intermediate","time":"7 पाठ","summary":"पोज़िशन साइज़, स्टॉप लॉस, एक्सपोज़र सीमा और ड्रॉडाउन योजना से पूँजी की रक्षा करें।"},"intraday-trading":{"title":"इंट्राडे ट्रेडिंग","level":"advanced","time":"9 पाठ","summary":"एक ही सत्र में ट्रेड करें। लिक्विडिटी, ऑर्डर निष्पादन, मार्जिन और असली जोखिम समझें।"},"futures-options":{"title":"फ्यूचर्स और ऑप्शंस (F&O)","level":"advanced","time":"12 पाठ","summary":"फ्यूचर्स, कॉल और पुट ऑप्शंस, स्ट्राइक, एक्सपायरी, मार्जिन और पेऑफ़ को उनके जोखिमों के साथ समझें।"},"option-greeks":{"title":"ऑप्शन ग्रीक्स और रणनीतियाँ","level":"advanced","time":"10 पाठ","summary":"कीमत, समय और अस्थिरता के साथ ऑप्शन की कीमत कैसे बदलती है, यह समझें और सीमित-जोखिम रणनीतियाँ बनाएँ।"},"trading-psychology":{"title":"ट्रेडिंग मनोविज्ञान","level":"advanced","time":"6 पाठ","summary":"डर, लालच और ओवरट्रेडिंग जैसे पूर्वाग्रह पहचानें और अनुशासित प्रक्रिया बनाएँ।"},"candlestick-patterns":{"title":"कैंडलस्टिक और चार्ट पैटर्न","level":"intermediate","time":"25 पैटर्न","summary":"हर कैंडल और चार्ट आकार का संकेत, उसका महत्व, पुष्टि कैसे करें, और कौन सी गलती से बचें, यह सीखें।"},"technical-indicators":{"title":"टेक्निकल इंडिकेटर","level":"intermediate","time":"10 इंडिकेटर","summary":"मूविंग एवरेज, RSI, MACD, वॉल्यूम और अन्य इंडिकेटर क्या मापते हैं, हर एक कब इस्तेमाल करें, और ट्रेड में कैसे इस्तेमाल करें, यह समझें।"},"tax-basics":{"title":"भारतीय निवेशकों और ट्रेडरों के लिए टैक्स बेसिक्स","level":"intermediate","time":"11 विषय","summary":"भारत में शेयर, म्यूचुअल फंड, इंट्राडे और F&O से होने वाले लाभ पर टैक्स कैसे लगता है, कौन से रिकॉर्ड रखें, और मौजूदा नियम कहाँ जाँचें।"},"balance-sheet":{"title":"बैलेंस शीट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"बैलेंस शीट क्या दिखाती है, संपत्ति, देनदारी और इक्विटी कैसे पढ़ें, और वित्तीय मज़बूती बताने वाले अनुपात।"},"cash-flow-statement":{"title":"कैश फ़्लो स्टेटमेंट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी का असली नकद कहाँ से आता और कहाँ जाता है, और कैश फ़्लो मुनाफ़े से ज़्यादा क्या बताता है।"},"quarterly-results":{"title":"तिमाही नतीजे कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"तिमाही नतीजों के आँकड़े कैसे पढ़ें, सही तुलना कैसे करें, और एक-बार की मदों को कैसे पहचानें।"},"annual-report":{"title":"सालाना रिपोर्ट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी की सालाना रिपोर्ट के हिस्से, हर हिस्सा क्या बताता है, और चेतावनी के संकेत।"},"shareholding-pattern":{"title":"शेयरहोल्डिंग पैटर्न और प्रमोटर होल्डिंग","level":"intermediate","time":"12 विषय","summary":"कंपनी का मालिक कौन है, प्रमोटर, संस्थागत और सार्वजनिक होल्डिंग कैसे बदलती है, और गिरवी शेयरों का क्या मतलब है।"},"valuation-basics":{"title":"वैल्यूएशन की मूल बातें: शेयर की क़ीमत क्या होनी चाहिए?","level":"advanced","time":"8 विषय","summary":"P/E, P/B, EV/EBITDA, PEG और डिस्काउंटेड कैश फ़्लो समझाए गए, उनकी सीमाओं के साथ और उन्हें मिलाकर कैसे इस्तेमाल करें।"},"corporate-actions":{"title":"कॉर्पोरेट एक्शन: डिविडेंड, बोनस, स्प्लिट, राइट्स और बायबैक","level":"intermediate","time":"13 विषय","summary":"कंपनियाँ शेयर और नकद के साथ क्या करती हैं, हर एक्शन कीमत और आपकी होल्डिंग को कैसे बदलता है, और एक्स-डेट पर भ्रम से कैसे बचें।"},"market-rules":{"title":"बाज़ार के नियम और निवेशक सुरक्षा","level":"beginner","time":"10 विषय","summary":"बाज़ार का समय, सेटलमेंट, प्राइस बैंड और सर्किट ब्रेकर, IPO में आवेदन, धोखाधड़ी और टिप्स पहचानना, और कुछ गलत होने पर शिकायत कैसे करें।"}}};
const LESSON_OVERRIDES = {"en":{"swing-trading":{"sections":[{"h":"1. What swing trading is","p":"Swing trading holds positions for days to a few weeks to capture a price swing. It sits between intraday trading (same day) and investing (months or years). It suits people with a job who can check the market once or twice a day, but it needs patience, a clear plan and a journal."},{"h":"2. The time you give a trade","p":"A swing trade is not an investment and not a day trade. You enter because of a setup, and you plan the maximum time you will hold it. If the trade does not move within that time, the setup has failed, and you exit even if the loss is small. Holding a losing trade for months is a different strategy, and it usually goes wrong.","ul":["Typical holding period: 3 to 20 sessions, decided before entry.","Overnight holding: gaps can open far beyond your stop, so position size must allow for this.","Market hours: you can plan on the daily chart after the close, and place orders for the next session."]},{"h":"3. Setups: the reasons to enter","p":"A setup is a repeatable situation with a clear rule. Common swing setups are a breakout above resistance on volume, a pullback to a rising moving average in an uptrend, a bullish reversal candle at support, and a range breakout after a squeeze. Write each setup as a rule, for example: close above the 20-day high with volume 1.5 times average, in an uptrend (price above the 50-day average)."},{"h":"4. Entry, stop and target: the complete plan","ul":["Entry: the price or condition that triggers the trade, for example a close above ₹250.","Stop-loss: where the idea is proven wrong, for example below the last swing low at ₹240. Place it before you enter.","Target: the level where you take profit, for example previous resistance at ₹270, or a multiple of risk.","Reward-to-risk: (target − entry) ÷ (entry − stop). Example: (270 − 250) ÷ (250 − 240) = 2. Many traders require at least 2."]},{"h":"5. Position sizing: the most important number","p":"Decide the maximum loss you accept on one trade, usually 0.5% to 2% of capital. The position size follows from the stop distance, not from how confident you feel.","p2":"Example: capital ₹1,00,000, risk 1% = ₹1,000. Entry ₹250, stop ₹240. Risk per share ₹10. Shares = 1,000 ÷ 10 = 100. Position value = ₹25,000 (25% of capital). The stop limits the loss to about ₹1,000 before costs and any gap."},{"h":"6. Trade management after entry","p":"Once in a trade, the plan decides your actions, not emotion. Move the stop up only as the trade proves itself, for example to break-even after the price moves 1 times the risk. Take partial profits at the first target if you want, and let the rest run with a trailing stop. Never widen a stop to avoid a loss.","ul":["Move to break-even after a move equal to your initial risk (example: +₹10 on a ₹10 risk).","Trail the stop below higher swing lows, or below a moving average.","Exit at the time limit if the trade has gone nowhere."]},{"h":"7. Gaps: the risk that breaks stops","p":"A gap is when the price opens far above or below the previous close, usually after news. A stop is an order to exit at a price, but in a gap the first available price may be much worse. Example: stop at ₹240, bad news, the stock opens at ₹230. The loss is ₹20 per share, double the planned ₹10. Reduce size before holding through events such as results, budgets and policy announcements."},{"h":"8. Sector and market context","p":"A good stock in a weak sector or a falling market often fails. Check the index trend and the sector trend before entering. Swing traders who follow strong sectors and the broad market tend to have higher success rates than those who trade single stocks in isolation."},{"h":"9. Keeping a swing trading journal","p":"Record the setup, reason, date, entry, stop, target, size, exit, result in rupees and in R (multiples of risk), and any mistake. Review monthly. Common findings: setups that do not work for you, exits that come too early, and stops that move against the plan."},{"h":"10. A worked example from start to finish","p":"A stock closes above its 20-day high at ₹250 with volume 1.5 times average, in an uptrend. You buy 100 shares at ₹250 with a stop at ₹240 and a target at ₹270. Three days later the price reaches ₹262; you move the stop to ₹250 (break-even). Two days later price falls back to ₹250 and exits. Loss: 0 before costs. Next setup: another breakout. The example shows that the stop protects the account even when the trade does not go your way."},{"h":"11. Common swing trading mistakes","ul":["Entering without a stop because the setup looks strong.","Moving the stop further away when the price approaches it.","Holding through earnings without deciding to do so.","Adding to a losing position to average down.","Trading too many setups at once, which leaves no capital for the best one."]},{"h":"13. Swing strategies: buy and sell rules","p":"Each strategy below has three parts: when the market condition fits, how to buy, and how to sell (stop-loss and profit target). Use one strategy at a time and write the rules before you trade. Results are shown as examples, not promises."},{"h":"Strategy 1: Breakout buy","p":"Buy when price closes above a clear resistance level on above-average volume. Best in an uptrend or after a base of consolidation.","ul":["Buy: close above resistance (for example ₹250) with volume at least 1.5 times the 20-day average.","Stop-loss: just below the breakout candle's low or the last swing low (for example ₹240).","Target: the height of the base added to the breakout, or the next resistance (for example ₹270). Risk-reward should be at least 1:2.","Sell early if: price closes back below the breakout level within 2 days. A failed breakout is an exit signal."],"p2":"Example: stock breaks ₹250 on 2 times average volume. Buy 100 shares at ₹250, stop ₹240 (risk ₹1,000). Target ₹270 (reward ₹2,000). Price closes at ₹266 after three days; move stop to ₹250 (break-even) and hold for the target.","img":{"file":"s1-breakout.svg","en":{"alt":"Price closes above resistance at 250 on a volume spike, with stop at 240 and target at 270","cap":"Breakout: entry above 250 on volume, stop below 240, target at 270."},"hi":{"alt":"Price closes above resistance at 250 on a volume spike, with stop at 240 and target at 270","cap":"Breakout: entry above 250 on volume, stop below 240, target at 270."}}},{"h":"Why it works","p":"Price that has been stuck under a level is building energy. A close above it, on volume, shows buyers have taken control of the level."},{"h":"Checklist before you buy","ul":["Resistance is clear and was tested at least twice","Volume on the breakout is at least 1.5 times average","The broader market and sector are not falling","Stop and target are written before the order"]},{"h":"Position size example","p":"Capital ₹1,00,000, risk 1%. Entry ₹250, stop ₹240 (₹10 per share). Shares = 1,000 ÷ 10 = 100. Position value ₹25,000."},{"h":"Strategy 2: Pullback to a rising moving average","p":"Buy a dip in a strong uptrend, when price returns to a rising moving average and shows buying interest. This gives a better price than buying the breakout.","ul":["Trend check: price above a rising 50-day average; 20-day average above 50-day.","Buy: price touches or nears the 20-day EMA and forms a bullish candle (hammer or engulfing) with RSI turning up from around 40 to 50.","Stop-loss: below the 50-day average or the pullback low.","Sell: at the previous swing high, or trail the stop below each new higher low."],"p2":"Example: in an uptrend, price falls to ₹248 (20-day EMA) and forms a bullish engulfing candle. Buy at ₹249, stop ₹243 (below the 50-day average), target the previous high ₹262 (risk ₹6, reward ₹13).","img":{"file":"s2-pullback.svg","en":{"alt":"Uptrend pulls back to a rising 20-day EMA, buy point marked","cap":"Pullback: buy near the rising 20-day EMA, stop below the 50-day average."},"hi":{"alt":"Uptrend pulls back to a rising 20-day EMA, buy point marked","cap":"Pullback: buy near the rising 20-day EMA, stop below the 50-day average."}}},{"h":"Why it works","p":"In a healthy uptrend, price often returns to a rising average before continuing. Buying there gives a better price and a closer stop than chasing the breakout."},{"h":"Checklist before you buy","ul":["Price is above a rising 50-day average","The 20-day average is above the 50-day average","The pullback is orderly, on lower volume","A bullish candle or RSI turn confirms the bounce"]},{"h":"Position size example","p":"Entry ₹249, stop ₹243 (₹6 risk). With ₹1,000 risk, shares = 1,000 ÷ 6 ≈ 166. Target ₹262 (₹13 reward) gives about 2.2 to 1."},{"h":"Strategy 3: Support bounce with confirmation","p":"Buy at a well-tested support level after a fall, only after a clear reversal signal. Works in range-bound stocks as well as at the bottom of a trend.","ul":["Level: support tested at least twice (for example ₹240) with volume falling on each test.","Buy: bullish reversal candle at support, followed by a close above that candle's high.","Stop-loss: just below support (for example ₹237).","Sell: at the middle of the range or at resistance (for example ₹255). Exit if support breaks on volume."],"img":{"file":"s3-support.svg","en":{"alt":"Price bounces from a tested support zone near 100 after a reversal candle","cap":"Support bounce: a reversal candle at tested support, with stop below the zone."},"hi":{"alt":"Price bounces from a tested support zone near 100 after a reversal candle","cap":"Support bounce: a reversal candle at tested support, with stop below the zone."}}},{"h":"Why it works","p":"A level that has held several times shows that buyers defend it. A reversal candle there tells you the defence is working right now."},{"h":"Checklist before you buy","ul":["Support has held at least twice","Volume falls on each test of support","The reversal candle closes above its own high","Stop sits below support, not inside the range"]},{"h":"Position size example","p":"Entry ₹241, stop ₹237 (₹4 risk). With ₹1,000 risk, shares = 250. Target ₹255 (₹14 reward) is about 3.5 to 1."},{"h":"Strategy 4: Trend-following exit (sell rules)","p":"Many swing traders hold until the trend breaks rather than fixing a target. This captures large moves and needs a clear exit rule.","ul":["Trailing stop: move the stop up to below each higher swing low.","Moving-average exit: sell when the price closes below the 20-day EMA after being above it.","Time exit: if the trade has not moved toward the target within the planned period (for example 15 sessions), sell and review.","Never move a stop down. Only tighten or keep it."],"img":{"file":"s4-trailing.svg","en":{"alt":"Price path with a trailing stop that steps up under each higher low","cap":"Trailing stop: move the stop up under each higher low; exit when the stop is hit."},"hi":{"alt":"Price path with a trailing stop that steps up under each higher low","cap":"Trailing stop: move the stop up under each higher low; exit when the stop is hit."}}},{"h":"Why it works","p":"Fixed targets can cut winners short. A trailing stop lets a trend run while locking in a rising floor under the price."},{"h":"Checklist before you buy","ul":["The trend is clear (higher highs and higher lows)","Each new stop sits below the latest higher low","The stop never moves down","A time limit is set in case the trend stops"]},{"h":"Position size example","p":"Entry ₹110, initial stop ₹104 (₹6 risk). Each higher low lifts the stop, so profit is protected as the trend continues."},{"h":"Strategy 5: Sell side (short) swing trades","p":"Short selling in swing trading means selling a stock you do not own, expecting it to fall. In India, short selling is limited to permitted stocks and products, and brokers apply margin rules. Only use it if you understand the rules and the unlimited-loss risk.","ul":["Setup: breakdown below support on volume, or a bearish reversal at resistance in a downtrend.","Stop-loss: just above the broken support, or above the recent swing high.","Target: the next support level, with reward at least twice the risk.","Check the stock is eligible for short selling and understand margin and settlement rules before trading."],"img":{"file":"s5-short.svg","en":{"alt":"Price breaks below support at 240 on volume; short stop above and target below","cap":"Short setup: break below support, stop above the broken level, target at the next support."},"hi":{"alt":"Price breaks below support at 240 on volume; short stop above and target below","cap":"Short setup: break below support, stop above the broken level, target at the next support."}}},{"h":"Why it works","p":"A break below support on volume means sellers have overcome a level that buyers defended before. Short selling profits from that failure of support."},{"h":"Checklist before you buy","ul":["Short selling is permitted for this stock","Margin and settlement rules are understood","Breakdown is on volume, not a thin day","Stop sits just above the broken support"]},{"h":"Position size example","p":"Entry ₹240, stop ₹246 (₹6 risk). The loss is unlimited if price rises, so use a hard stop and keep size small."},{"h":"Choosing a swing strategy","ul":["Trending market with a clear uptrend: pullback to a rising average (Strategy 2) or breakout (Strategy 1).","Range-bound market: support bounce (Strategy 3), selling near resistance.","Strong trend already running: trend-following exit (Strategy 4) to keep the winner.","Falling market with a breakdown: short setup (Strategy 5), only if permitted and understood."]},{"h":"Common swing strategy mistakes","ul":["Buying a breakout that has already run 5 percent past the level, which leaves little room to the stop.","Taking a pullback entry without a stop below the average.","Moving targets further up when price reaches them instead of taking profit or trailing the stop.","Using all five strategies at once. Pick one, test it, and keep a journal of results."]}]}},"hi":{"swing-trading":{"sections":[{"h":"1. स्विंग ट्रेडिंग क्या है","p":"स्विंग ट्रेडिंग कीमत की एक चाल पकड़ने के लिए पोज़िशन कुछ दिनों से कुछ हफ़्तों तक रखती है। यह इंट्राडे (उसी दिन) और निवेश (महीने या साल) के बीच आता है। यह उन लोगों के लिए उपयुक्त है जिनकी नौकरी है और जो दिन में एक-दो बार बाज़ार देख सकते हैं, पर इसके लिए धैर्य, साफ़ योजना और जर्नल चाहिए।"},{"h":"2. ट्रेड को कितना समय देना है","p":"स्विंग ट्रेड न निवेश है, न डे ट्रेड। आप सेटअप के कारण एंट्री करते हैं, और अधिकतम समय पहले से तय करते हैं। अगर ट्रेड उस समय में नहीं चलता, तो सेटअप विफल है, और छोटे नुकसान में भी बाहर निकलते हैं। घाटे वाला ट्रेड महीनों तक रखना एक अलग रणनीति है, और आमतौर पर वह ग़लत जाती है।","ul":["आमतौर पर होल्डिंग अवधि: एंट्री से पहले तय 3 से 20 सत्र।","रात भर होल्डिंग: गैप स्टॉप से बहुत दूर खुल सकते हैं, इसलिए पोज़िशन साइज़ में इसका हिसाब हो।","बाज़ार समय: दैनिक चार्ट पर बंद होने के बाद योजना बनाएँ, और अगले सत्र के लिए ऑर्डर दें।"]},{"h":"3. सेटअप: एंट्री के कारण","p":"सेटअप एक दोहराने योग्य स्थिति है, जिसका साफ़ नियम हो। आम स्विंग सेटअप: वॉल्यूम के साथ रेज़िस्टेंस के ऊपर ब्रेकआउट, अपट्रेंड में बढ़ते मूविंग एवरेज तक पुलबैक, सपोर्ट पर तेज़ी का पलटाव कैंडल, और स्क्वीज़ के बाद रेंज ब्रेकआउट। हर सेटअप को नियम के रूप में लिखें, जैसे: अपट्रेंड (कीमत 50-दिन एवरेज के ऊपर) में, वॉल्यूम औसत के 1.5 गुना के साथ 20-दिन के हाई के ऊपर क्लोज़।"},{"h":"4. एंट्री, स्टॉप और टारगेट: पूरी योजना","ul":["एंट्री: वह कीमत या शर्त जो ट्रेड शुरू करे, जैसे ₹250 के ऊपर क्लोज़।","स्टॉप-लॉस: वह स्तर जहाँ विचार ग़लत साबित होता है, जैसे ₹240 पर पिछले स्विंग लो के नीचे। एंट्री से पहले लगाएँ।","टारगेट: वह स्तर जहाँ मुनाफ़ा लेंगे, जैसे ₹270 पर पिछला रेज़िस्टेंस, या जोखिम का गुणक।","जोखिम-इनाम: (टारगेट − एंट्री) ÷ (एंट्री − स्टॉप)। उदाहरण: (270 − 250) ÷ (250 − 240) = 2। कई ट्रेडर कम से कम 2 चाहते हैं।"]},{"h":"5. पोज़िशन साइज़: सबसे महत्वपूर्ण संख्या","p":"तय करें कि एक ट्रेड में अधिकतम कितना नुकसान स्वीकार है, आमतौर पर पूँजी का 0.5% से 2%। पोज़िशन का आकार स्टॉप की दूरी से तय होता है, इस भावना से नहीं कि आप कितने आश्वस्त हैं।","p2":"उदाहरण: पूँजी ₹1,00,000, जोखिम 1% = ₹1,000। एंट्री ₹250, स्टॉप ₹240। प्रति शेयर जोखिम ₹10। शेयर = 1,000 ÷ 10 = 100। पोज़िशन का मूल्य ₹25,000 (पूँजी का 25%)। स्टॉप नुकसान को शुल्क और किसी गैप से पहले लगभग ₹1,000 तक सीमित रखता है।"},{"h":"6. एंट्री के बाद ट्रेड प्रबंधन","p":"एंट्री के बाद योजना तय करती है कि आप क्या करें, भावना नहीं। स्टॉप तभी ऊपर ले जाएँ जब ट्रेड खुद को साबित करे, जैसे कीमत आपके जोखिम जितनी चलने पर ब्रेक-ईवन पर। चाहें तो पहले टारगेट पर आंशिक मुनाफ़ा लें, और बाक़ी को ट्रेलिंग स्टॉप के साथ चलने दें। नुकसान से बचने के लिए स्टॉप कभी चौड़ा न करें।","ul":["प्रारंभिक जोखिम जितनी चाल पर ब्रेक-ईवन पर जाएँ (उदाहरण: ₹10 जोखिम पर +₹10)।","ऊँचे स्विंग लो के नीचे, या मूविंग एवरेज के नीचे स्टॉप ट्रेल करें।","अगर ट्रेड समय सीमा में कहीं नहीं पहुँचा तो समय सीमा पर बाहर निकलें।"]},{"h":"7. गैप: वह जोखिम जो स्टॉप तोड़ता है","p":"गैप तब होता है जब कीमत पिछले क्लोज़ से काफ़ी ऊपर या नीचे खुलती है, आमतौर पर ख़बर के बाद। स्टॉप कीमत पर बाहर निकलने का ऑर्डर है, पर गैप में पहली उपलब्ध कीमत कहीं बदतर हो सकती है। उदाहरण: ₹240 पर स्टॉप, बुरी ख़बर, शेयर ₹230 पर खुला। प्रति शेयर नुकसान ₹20 है, योजना के ₹10 का दोगुना। नतीजे, बजट और नीति घोषणाओं जैसी घटनाओं से पहले पोज़िशन घटाएँ।"},{"h":"8. सेक्टर और बाज़ार का संदर्भ","p":"कमज़ोर सेक्टर या गिरते बाज़ार में अच्छा शेयर भी अक्सर विफल होता है। एंट्री से पहले इंडेक्स और सेक्टर का ट्रेंड जाँचें। मज़बूत सेक्टरों और व्यापक बाज़ार के साथ चलने वाले स्विंग ट्रेडर अकेले शेयर में ट्रेड करने वालों से अक्सर बेहतर सफलता दर रखते हैं।"},{"h":"9. स्विंग ट्रेडिंग जर्नल","p":"सेटअप, कारण, तारीख़, एंट्री, स्टॉप, टारगेट, साइज़, एग्ज़िट, रुपये में नतीजा और R में नतीजा (जोखिम के गुणक), और कोई गलती लिखें। महीने में एक बार समीक्षा करें। आम खोज: कुछ सेटअप आपके लिए काम नहीं करते, एग्ज़िट बहुत जल्दी आते हैं, और स्टॉप योजना के ख़िलाफ़ खिसकते हैं।"},{"h":"10. शुरू से अंत तक एक उदाहरण","p":"एक शेयर 20-दिन के हाई से ऊपर ₹250 पर वॉल्यूम औसत के 1.5 गुना के साथ, अपट्रेंड में, क्लोज़ होता है। आप ₹250 पर 100 शेयर ख़रीदते हैं, स्टॉप ₹240 और टारगेट ₹270 पर। तीन दिन बाद कीमत ₹262 पहुँचती है; आप स्टॉप ₹250 (ब्रेक-ईवन) पर ले जाते हैं। दो दिन बाद कीमत ₹250 पर लौटती है और आप बाहर निकलते हैं। नुकसान: शुल्क से पहले 0। अगला सेटअप: एक और ब्रेकआउट। उदाहरण दिखाता है कि ट्रेड उम्मीद के उलट जाए तब भी स्टॉप खाते की रक्षा करता है।"},{"h":"11. आम स्विंग ट्रेडिंग गलतियाँ","ul":["सेटअप मज़बूत लगने पर बिना स्टॉप के एंट्री।","कीमत स्टॉप के पास आते ही उसे और दूर खिसकाना।","बिना फ़ैसले के नतीजों (results) के दौरान होल्ड करना।","घाटे वाली पोज़िशन में औसत बढ़ाने के लिए और ख़रीदना।","एक साथ बहुत सारे सेटअप लेना, जिससे सबसे अच्छे के लिए पूँजी न बचे।"]},{"h":"13. स्विंग रणनीतियाँ: ख़रीद और बिक्री के नियम","p":"नीचे हर रणनीति के तीन हिस्से हैं: बाज़ार की कौन सी स्थिति उपयुक्त है, कैसे ख़रीदें, और कैसे बेचें (स्टॉप-लॉस और लाभ का टारगेट)। एक समय में एक रणनीति इस्तेमाल करें और ट्रेड से पहले नियम लिख लें। नतीजे केवल उदाहरण हैं, वादा नहीं।"},{"h":"रणनीति 1: ब्रेकआउट ख़रीद","p":"जब कीमत औसत से ज़्यादा वॉल्यूम पर किसी साफ़ रेज़िस्टेंस के ऊपर क्लोज़ करे, तब ख़रीदें। अपट्रेंड में या समेकन (consolidation) के बाद सबसे अच्छा।","ul":["ख़रीद: 20-दिन के औसत वॉल्यूम के कम से कम 1.5 गुना वॉल्यूम के साथ रेज़िस्टेंस (जैसे ₹250) के ऊपर क्लोज़।","स्टॉप-लॉस: ब्रेकआउट कैंडल के लो के ठीक नीचे या पिछले स्विंग लो के नीचे (जैसे ₹240)।","टारगेट: समेकन की ऊँचाई को ब्रेकआउट में जोड़ें, या अगला रेज़िस्टेंस (जैसे ₹270)। जोखिम-इनाम कम से कम 1:2 हो।","जल्दी बेचें यदि: 2 दिन के भीतर कीमत ब्रेकआउट स्तर के नीचे क्लोज़ हो। विफल ब्रेकआउट एग्ज़िट संकेत है।"],"p2":"उदाहरण: शेयर औसत के 2 गुना वॉल्यूम पर ₹250 के ऊपर टूटता है। ₹250 पर 100 शेयर ख़रीदें, स्टॉप ₹240 (जोखिम ₹1,000)। टारगेट ₹270 (इनाम ₹2,000)। तीन दिन बाद क्लोज़ ₹266; स्टॉप ₹250 (ब्रेक-ईवन) पर ले जाएँ और टारगेट तक रखें।","img":{"file":"s1-breakout.svg","en":{"alt":"कीमत वॉल्यूम स्पाइक के साथ 250 के रेज़िस्टेंस के ऊपर क्लोज़, स्टॉप 240 और टारगेट 270","cap":"ब्रेकआउट: वॉल्यूम के साथ 250 के ऊपर एंट्री, 240 के नीचे स्टॉप, टारगेट 270।"},"hi":{"alt":"कीमत वॉल्यूम स्पाइक के साथ 250 के रेज़िस्टेंस के ऊपर क्लोज़, स्टॉप 240 और टारगेट 270","cap":"ब्रेकआउट: वॉल्यूम के साथ 250 के ऊपर एंट्री, 240 के नीचे स्टॉप, टारगेट 270।"}}},{"h":"यह क्यों काम करता है","p":"जो कीमत किसी स्तर के नीचे अटकी हो, वह ऊर्जा जमा करती है। वॉल्यूम के साथ उसके ऊपर क्लोज़ दिखाता है कि ख़रीदारों ने उस स्तर पर नियंत्रण ले लिया है।"},{"h":"ख़रीदने से पहले चेकलिस्ट","ul":["रेज़िस्टेंस साफ़ हो और कम से कम दो बार परखा गया हो","ब्रेकआउट पर वॉल्यूम औसत के कम से कम 1.5 गुना हो","व्यापक बाज़ार और सेक्टर न गिर रहे हों","ऑर्डर से पहले स्टॉप और टारगेट लिख लिए हों"]},{"h":"पोज़िशन साइज़ का उदाहरण","p":"पूँजी ₹1,00,000, जोखिम 1%। एंट्री ₹250, स्टॉप ₹240 (प्रति शेयर ₹10)। शेयर = 1,000 ÷ 10 = 100। पोज़िशन मूल्य ₹25,000।"},{"h":"रणनीति 2: बढ़ते मूविंग एवरेज तक पुलबैक","p":"मज़बूत अपट्रेंड में गिरावट पर ख़रीदें, जब कीमत बढ़ते मूविंग एवरेज तक लौटे और ख़रीदारी दिखाए। ब्रेकआउट ख़रीदने से यह बेहतर कीमत देता है।","ul":["ट्रेंड जाँच: कीमत बढ़ते 50-दिन एवरेज के ऊपर; 20-दिन एवरेज 50-दिन के ऊपर।","ख़रीद: कीमत 20-दिन के EMA को छुए या उसके पास आए और तेज़ी वाली कैंडल (हैमर या एंगल्फ़िंग) बने, RSI लगभग 40 से 50 के बीच से ऊपर मुड़े।","स्टॉप-लॉस: 50-दिन एवरेज या पुलबैक के लो के नीचे।","बिक्री: पिछले स्विंग हाई पर, या हर नए हायर लो के नीचे स्टॉप ट्रेल करें।"],"p2":"उदाहरण: अपट्रेंड में कीमत ₹248 (20-दिन EMA) तक गिरती है और तेज़ी वाली एंगल्फ़िंग कैंडल बनाती है। ₹249 पर ख़रीदें, स्टॉप ₹243 (50-दिन एवरेज के नीचे), टारगेट पिछला हाई ₹262 (जोखिम ₹6, इनाम ₹13)।","img":{"file":"s2-pullback.svg","en":{"alt":"अपट्रेंड में कीमत बढ़ते 20-दिन EMA तक लौटती है, ख़रीद बिंदु चिह्नित","cap":"पुलबैक: बढ़ते 20-दिन EMA के पास ख़रीदें, 50-दिन एवरेज के नीचे स्टॉप।"},"hi":{"alt":"अपट्रेंड में कीमत बढ़ते 20-दिन EMA तक लौटती है, ख़रीद बिंदु चिह्नित","cap":"पुलबैक: बढ़ते 20-दिन EMA के पास ख़रीदें, 50-दिन एवरेज के नीचे स्टॉप।"}}},{"h":"यह क्यों काम करता है","p":"स्वस्थ अपट्रेंड में कीमत आगे बढ़ने से पहले अक्सर बढ़ते एवरेज तक लौटती है। वहाँ ख़रीदने से ब्रेकआउट का पीछा करने से बेहतर कीमत और पास का स्टॉप मिलता है।"},{"h":"ख़रीदने से पहले चेकलिस्ट","ul":["कीमत बढ़ते 50-दिन एवरेज के ऊपर हो","20-दिन एवरेज 50-दिन एवरेज के ऊपर हो","पुलबैक व्यवस्थित हो, कम वॉल्यूम पर","तेज़ी वाली कैंडल या RSI का मुड़ना उछाल की पुष्टि करे"]},{"h":"पोज़िशन साइज़ का उदाहरण","p":"एंट्री ₹249, स्टॉप ₹243 (जोखिम ₹6)। ₹1,000 जोखिम पर शेयर = 1,000 ÷ 6 ≈ 166। टारगेट ₹262 (इनाम ₹13) लगभग 2.2 गुना।"},{"h":"रणनीति 3: सपोर्ट पर पलटाव की पुष्टि","p":"गिरावट के बाद अच्छी तरह परखे गए सपोर्ट स्तर पर ख़रीदें, पर केवल साफ़ पलटाव संकेत के बाद। रेंज वाले शेयरों और ट्रेंड के निचले स्तर दोनों पर काम करता है।","ul":["स्तर: सपोर्ट (जैसे ₹240) की कम से कम दो बार परख, हर परख पर वॉल्यूम घटता हुआ।","ख़रीद: सपोर्ट पर तेज़ी वाली पलटाव कैंडल, और उसके बाद उसके हाई के ऊपर क्लोज़।","स्टॉप-लॉस: सपोर्ट के ठीक नीचे (जैसे ₹237)।","बिक्री: रेंज के मध्य या रेज़िस्टेंस (जैसे ₹255) पर। वॉल्यूम के साथ सपोर्ट टूटे तो बाहर निकलें।"],"img":{"file":"s3-support.svg","en":{"alt":"लगभग 100 के परखे सपोर्ट ज़ोन से पलटाव कैंडल के बाद कीमत उछलती है","cap":"सपोर्ट पर पलटाव: परखे गए स्तर पर पलटाव कैंडल, ज़ोन के नीचे स्टॉप।"},"hi":{"alt":"लगभग 100 के परखे सपोर्ट ज़ोन से पलटाव कैंडल के बाद कीमत उछलती है","cap":"सपोर्ट पर पलटाव: परखे गए स्तर पर पलटाव कैंडल, ज़ोन के नीचे स्टॉप।"}}},{"h":"यह क्यों काम करता है","p":"जो स्तर कई बार टिका हो, वह दिखाता है कि ख़रीदार उसका बचाव कर रहे हैं। वहाँ पलटाव कैंडल बताता है कि अभी बचाव काम कर रहा है।"},{"h":"ख़रीदने से पहले चेकलिस्ट","ul":["सपोर्ट कम से कम दो बार टिका हो","हर परख पर वॉल्यूम घटे","पलटाव कैंडल अपने हाई के ऊपर क्लोज़ हो","स्टॉप सपोर्ट के नीचे हो, रेंज के अंदर नहीं"]},{"h":"पोज़िशन साइज़ का उदाहरण","p":"एंट्री ₹241, स्टॉप ₹237 (जोखिम ₹4)। ₹1,000 जोखिम पर शेयर = 250। टारगेट ₹255 (इनाम ₹14) लगभग 3.5 गुना।"},{"h":"रणनीति 4: ट्रेंड-फ़ॉलोइंग एग्ज़िट (बिक्री के नियम)","p":"कई स्विंग ट्रेडर तय टारगेट के बजाय ट्रेंड टूटने तक रुकते हैं। इससे बड़ी चालें पकड़ी जाती हैं, पर बिक्री का साफ़ नियम चाहिए।","ul":["ट्रेलिंग स्टॉप: हर नए हायर लो के नीचे स्टॉप ऊपर ले जाएँ।","मूविंग-एवरेज एग्ज़िट: 20-दिन EMA के ऊपर रहने के बाद उसके नीचे क्लोज़ होने पर बेचें।","समय एग्ज़िट: यदि तय अवधि (जैसे 15 सत्र) में ट्रेड टारगेट की ओर नहीं गया, तो बेचें और समीक्षा करें।","स्टॉप कभी नीचे न खिसकाएँ। केवल ऊपर ले जाएँ या वैसा ही रखें।"],"img":{"file":"s4-trailing.svg","en":{"alt":"कीमत का पथ जिसमें ट्रेलिंग स्टॉप हर हायर लो के नीचे ऊपर जाता है","cap":"ट्रेलिंग स्टॉप: हर हायर लो के नीचे स्टॉप ऊपर ले जाएँ; स्टॉप लगने पर बाहर निकलें।"},"hi":{"alt":"कीमत का पथ जिसमें ट्रेलिंग स्टॉप हर हायर लो के नीचे ऊपर जाता है","cap":"ट्रेलिंग स्टॉप: हर हायर लो के नीचे स्टॉप ऊपर ले जाएँ; स्टॉप लगने पर बाहर निकलें।"}}},{"h":"यह क्यों काम करता है","p":"तय टारगेट विजेता ट्रेड को जल्दी काट सकते हैं। ट्रेलिंग स्टॉप ट्रेंड को चलने देता है और कीमत के नीचे बढ़ती मंज़िल तय करता है।"},{"h":"ख़रीदने से पहले चेकलिस्ट","ul":["ट्रेंड साफ़ हो (ऊँचे हाई और ऊँचे लो)","हर नया स्टॉप ताज़ा हायर लो के नीचे हो","स्टॉप कभी नीचे न खिसके","ट्रेंड रुकने की स्थिति में समय सीमा तय हो"]},{"h":"पोज़िशन साइज़ का उदाहरण","p":"एंट्री ₹110, शुरुआती स्टॉप ₹104 (जोखिम ₹6)। हर हायर लो स्टॉप ऊपर ले जाता है, इसलिए ट्रेंड जारी रहने पर लाभ सुरक्षित होता है।"},{"h":"रणनीति 5: बिक्री पक्ष (शॉर्ट) स्विंग ट्रेड","p":"स्विंग ट्रेडिंग में शॉर्ट सेलिंग का मतलब है ऐसे शेयर बेचना जो आपके पास नहीं, इस उम्मीद में कि कीमत गिरेगी। भारत में शॉर्ट सेलिंग अनुमत शेयरों और उत्पादों तक सीमित है, और ब्रोकर मार्जिन नियम लगाते हैं। इसे केवल तब इस्तेमाल करें जब नियम और असीमित नुकसान के जोखिम की समझ हो।","ul":["सेटअप: मंदी के ट्रेंड में वॉल्यूम के साथ सपोर्ट के नीचे ब्रेकडाउन, या रेज़िस्टेंस पर बियरिश पलटाव।","स्टॉप-लॉस: टूटे सपोर्ट के ठीक ऊपर, या हाल के स्विंग हाई के ऊपर।","टारगेट: अगला सपोर्ट स्तर, जिसमें इनाम जोखिम का कम से कम दोगुना हो।","ट्रेड से पहले जाँचें कि शेयर शॉर्ट योग्य है, और मार्जिन व सेटलमेंट नियम समझें।"],"img":{"file":"s5-short.svg","en":{"alt":"कीमत वॉल्यूम के साथ 240 के सपोर्ट के नीचे टूटती है; ऊपर स्टॉप और नीचे टारगेट","cap":"शॉर्ट सेटअप: सपोर्ट का टूटना, टूटे स्तर के ऊपर स्टॉप, अगले सपोर्ट पर टारगेट।"},"hi":{"alt":"कीमत वॉल्यूम के साथ 240 के सपोर्ट के नीचे टूटती है; ऊपर स्टॉप और नीचे टारगेट","cap":"शॉर्ट सेटअप: सपोर्ट का टूटना, टूटे स्तर के ऊपर स्टॉप, अगले सपोर्ट पर टारगेट।"}}},{"h":"यह क्यों काम करता है","p":"वॉल्यूम के साथ सपोर्ट के नीचे टूटना दिखाता है कि विक्रेताओं ने वह स्तर पार कर लिया है जिसे ख़रीदार पहले बचाते थे। शॉर्ट सेलिंग इसी सपोर्ट की विफलता से लाभ लेती है।"},{"h":"ख़रीदने से पहले चेकलिस्ट","ul":["इस शेयर में शॉर्ट सेलिंग अनुमत हो","मार्जिन और सेटलमेंट नियम समझे हों","ब्रेकडाउन वॉल्यूम के साथ हो, पतले दिन पर नहीं","स्टॉप टूटे सपोर्ट के ठीक ऊपर हो"]},{"h":"पोज़िशन साइज़ का उदाहरण","p":"एंट्री ₹240, स्टॉप ₹246 (जोखिम ₹6)। कीमत बढ़ी तो नुकसान असीमित हो सकता है, इसलिए सख़्त स्टॉप रखें और साइज़ छोटा रखें।"},{"h":"स्विंग रणनीति कैसे चुनें","ul":["साफ़ अपट्रेंड वाला बाज़ार: बढ़ते एवरेज पर पुलबैक (रणनीति 2) या ब्रेकआउट (रणनीति 1)।","रेंज वाला बाज़ार: सपोर्ट पर पलटाव (रणनीति 3), रेज़िस्टेंस के पास बेचना।","पहले से चलता मज़बूत ट्रेंड: जीत को बनाए रखने के लिए ट्रेंड-फ़ॉलोइंग एग्ज़िट (रणनीति 4)।","गिरता बाज़ार जिसमें ब्रेकडाउन हो: शॉर्ट सेटअप (रणनीति 5), केवल तब जब अनुमति हो और समझ हो।"]},{"h":"आम स्विंग रणनीति गलतियाँ","ul":["ऐसा ब्रेकआउट ख़रीदना जो स्तर से 5% आगे निकल चुका हो, जिससे स्टॉप तक जगह कम बचे।","औसत के नीचे स्टॉप लगाए बिना पुलबैक एंट्री लेना।","टारगेट पर पहुँचने पर टारगेट और ऊपर खिसकाना, बजाय मुनाफ़ा लेने या स्टॉप ट्रेल करने के।","पाँचों रणनीतियाँ एक साथ इस्तेमाल करना। एक चुनें, परखें, और नतीजों का जर्नल रखें।"]}]}}};
const LESSON_EXTRAS_EN = {"swing-trading":{"examples":[{"title":"A complete swing trade","text":"Stock at ₹250 breaks resistance. Entry ₹250, stop ₹240, target ₹270. Risk = ₹10 per share, reward = ₹20, so the ratio is 2:1. With 100 shares: if the target hits, profit ≈ ₹2,000 (2% of ₹1 lakh capital). If the stop hits, loss ≈ ₹1,000 (1%)."},{"title":"Expectancy over many trades","text":"Win rate 40%, average win 2R, average loss 1R (R = the planned risk). Expectancy = 0.4 × 2 − 0.6 × 1 = +0.2R per trade. A system can be profitable with a win rate below 50% if winners are larger than losers."}],"scenarios":[{"title":"Gap down past your stop","text":"You hold overnight with a stop at ₹240. Bad news sends the stock to open at ₹230. Your stop fills near ₹230, so the loss is ₹20 per share (2%), not the planned ₹10 (1%). Position sizing should assume some gap risk."},{"title":"Sideways market for two weeks","text":"The stock moves in a tight range for ten sessions and your target is not reached. Time has a cost. Decide in advance how long you will hold a trade that does not move."}],"useCases":["Trading pullbacks to a rising moving average during an established trend.","Trading around earnings season, with position size reduced to account for gap risk.","Following sector rotation, buying the strongest sector's leaders over several weeks."],"takeaways":["Write the setup, entry, stop and target before entering.","Position size from the stop distance, not from a hunch.","Expectancy, not the win rate alone, decides whether a method is worth using.","Review each trade in a journal to find what really works."],"practice":[{"q":"Entry ₹400, stop ₹388, target ₹424. What is the reward-to-risk ratio?","a":"Risk ₹12, reward ₹24, ratio 2:1."},{"q":"With ₹1,00,000 capital and 1% risk, entry ₹400 and stop ₹388, how many shares?","a":"Risk ₹1,000 ÷ ₹12 per share = 83 shares (rounded down)."},{"q":"Win rate 50%, average win 1.5R, average loss 1R. Is expectancy positive?","a":"0.5 × 1.5 − 0.5 × 1 = +0.25R per trade. Yes, before costs."}]}};
const LESSON_EXTRAS_HI = {"swing-trading":{"examples":[{"title":"एक पूरा स्विंग ट्रेड","text":"₹250 का शेयर रेज़िस्टेंस तोड़ता है। एंट्री ₹250, स्टॉप ₹240, टारगेट ₹270। जोखिम प्रति शेयर ₹10, इनाम ₹20, अनुपात 2:1। 100 शेयर पर: टारगेट लगे तो लाभ ≈ ₹2,000 (₹1 लाख पूँजी का 2%)। स्टॉप लगे तो नुकसान ≈ ₹1,000 (1%)।"},{"title":"कई ट्रेडों में अपेक्षित मूल्य (expectancy)","text":"जीत दर 40%, औसत जीत 2R, औसत नुकसान 1R (R = नियोजित जोखिम)। Expectancy = 0.4 × 2 − 0.6 × 1 = प्रति ट्रेड +0.2R। अगर विजेता ट्रेड हारने वालों से बड़े हों, तो 50% से कम जीत दर पर भी सिस्टम लाभदायक हो सकता है।"}],"scenarios":[{"title":"गैप डाउन होकर स्टॉप से नीचे","text":"आपने ₹240 के स्टॉप के साथ पोज़िशन रात भर रखी। बुरी ख़बर से शेयर ₹230 पर खुलता है। आपका स्टॉप लगभग ₹230 पर पूरा होता है, इसलिए प्रति शेयर नुकसान ₹20 (2%) है, नियोजित ₹10 (1%) नहीं। पोज़िशन साइज़ तय करते समय गैप का जोखिम भी मानें।"},{"title":"दो हफ़्ते बाज़ार बिना दिशा के","text":"शेयर दस सत्रों तक तंग रेंज में घूमता है और टारगेट नहीं छूता। समय की भी कीमत होती है। पहले से तय करें कि जो ट्रेड नहीं चलता, उसे कितने दिन रखेंगे।"}],"useCases":["स्थापित ट्रेंड में बढ़ते मूविंग एवरेज तक पुलबैक पर ट्रेड करना।","नतीजों के मौसम में ट्रेड, गैप जोखिम के लिए पोज़िशन छोटी रखकर।","सेक्टर रोटेशन: सबसे मज़बूत सेक्टर के अग्रणी शेयर कुछ हफ़्तों तक ख़रीदना।"],"takeaways":["एंट्री से पहले सेटअप, एंट्री, स्टॉप और टारगेट लिख लें।","पोज़िशन साइज़ स्टॉप की दूरी से तय करें, अनुमान से नहीं।","कोई तरीका उपयोगी है या नहीं, यह अकेली जीत दर नहीं, expectancy बताती है।","हर ट्रेड की जर्नल में समीक्षा करें ताकि पता चले कि असल में क्या काम करता है।"],"practice":[{"q":"एंट्री ₹400, स्टॉप ₹388, टारगेट ₹424। जोखिम-इनाम अनुपात क्या है?","a":"जोखिम ₹12, इनाम ₹24, अनुपात 2:1।"},{"q":"₹1,00,000 पूँजी, 1% जोखिम, एंट्री ₹400 और स्टॉप ₹388। कितने शेयर?","a":"जोखिम ₹1,000 ÷ प्रति शेयर ₹12 = 83 शेयर (नीचे पूर्णांक)।"},{"q":"जीत दर 50%, औसत जीत 1.5R, औसत नुकसान 1R। क्या expectancy सकारात्मक है?","a":"0.5 × 1.5 − 0.5 × 1 = प्रति ट्रेड +0.25R। हाँ, शुल्क से पहले।"}]}};
