function glossarySlug(en) {
 return en.toLowerCase().replace(/&/g, " and ").replace(/\b([a-z])\/([a-z])\b/g, "$1$2").replace(/['’+.]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}
function glossaryHref(en) {
 return `glossary-${glossarySlug(en)}.html`;
}
